  const slices = [
    { id: 'one', message: 'one', paths: ['package.json'] },
    { id: 'two', message: 'two', paths: ['src/assets/'] },
    { id: 'three', message: 'three', paths: ['src/assets/base.css'] }
  ]
  const { assigned, leftovers } = classify(
    parsePorcelain(
