import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

/** Absolute path of the `client/` project this driver commits. */
export const CLIENT_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')

/**
